\set ON_ERROR_STOP on
-- B65: cierra la búsqueda de tipos de la clausura externa.
-- Conserva cuerpos, firmas, OID, propietarios, ACL, canon e historia.
-- Requiere B60/B61. No reaplicar sobre una instalación ya corregida.
BEGIN;
SET LOCAL search_path=pg_catalog,pg_temp;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
SELECT pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('bolsa_llamamientos:migracion:externa:000065',0));
