  ('vec_bolsa_llamamientos.solicitar_portal_candidato_v1(text,text,text,text,text,timestamp with time zone,timestamp with time zone,text[],text,text,timestamp with time zone,bytea,bytea,bytea,bytea,numeric,numeric,bytea,bytea,bytea,bytea)','a1d8bf50f4eebfda08514a7d12c1c98da477ad42258fda5bdb745b61fe09e2ab',true,'["search_path=pg_catalog", "lock_timeout=2s"]'::jsonb,'[{"grantee": "vec_bolsa_llamamientos_ejecutor", "grantor": "vec_bolsa_llamamientos_propietario", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "vec_bolsa_llamamientos_portal_externo", "grantor": "vec_bolsa_llamamientos_propietario", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "vec_bolsa_llamamientos_propietario", "grantor": "vec_bolsa_llamamientos_propietario", "grantable": false, "privilege": "EXECUTE"}]'::jsonb),
  ('vec_bolsa_llamamientos.solicitud_portal_pendiente_v1(text)','66cd081efbec9a3bf86c1fb0d2b0090a1529b9694c8ff80c114f860acf530e6d',true,'["search_path=pg_catalog"]'::jsonb,'[{"grantee": "vec_bolsa_llamamientos_propietario", "grantor": "vec_bolsa_llamamientos_propietario", "grantable": false, "privilege": "EXECUTE"}]'::jsonb)
 ) AS inventario(firma,huella,definidor,configuracion,acl) LOOP
  SELECT p.* INTO antes FROM pg_catalog.pg_proc p WHERE p.oid=pg_catalog.to_regprocedure(esperado.firma);
  IF NOT FOUND THEN RAISE EXCEPTION 'B65: preimagen incompatible para %',esperado.firma USING ERRCODE='55000'; END IF;
  SELECT coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'grantee',r.rolname,'grantor',g.rolname,'grantable',a.is_grantable,'privilege',a.privilege_type)
    ORDER BY r.rolname,g.rolname,a.privilege_type,a.is_grantable),'[]'::pg_catalog.jsonb)
  INTO acl_actual FROM pg_catalog.aclexplode(coalesce(antes.proacl,pg_catalog.acldefault('f',antes.proowner))) a
  LEFT JOIN pg_catalog.pg_roles r ON r.oid=a.grantee LEFT JOIN pg_catalog.pg_roles g ON g.oid=a.grantor;
  IF antes.proowner IS DISTINCT FROM pg_catalog.to_regrole('vec_bolsa_llamamientos_propietario')
     OR antes.prosecdef IS DISTINCT FROM esperado.definidor
     OR pg_catalog.to_jsonb(antes.proconfig) IS DISTINCT FROM esperado.configuracion
     OR pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(antes.prosrc,'UTF8')),'hex') IS DISTINCT FROM esperado.huella
     OR acl_actual IS DISTINCT FROM esperado.acl THEN
   RAISE EXCEPTION 'B65: preimagen incompatible para %',esperado.firma USING ERRCODE='55000';
  END IF;
  EXECUTE pg_catalog.format('ALTER FUNCTION %s SET search_path=pg_catalog,pg_temp',antes.oid::pg_catalog.regprocedure);
  SELECT p.* INTO STRICT despues FROM pg_catalog.pg_proc p WHERE p.oid=antes.oid;
  IF pg_catalog.to_jsonb(despues)-'proconfig' IS DISTINCT FROM pg_catalog.to_jsonb(antes)-'proconfig'
     OR (SELECT pg_catalog.array_agg(CASE WHEN opcion='search_path=pg_catalog' THEN 'search_path=pg_catalog, pg_temp' ELSE opcion END ORDER BY indice)
         FROM pg_catalog.unnest(antes.proconfig) WITH ORDINALITY AS opciones(opcion,indice)) IS DISTINCT FROM despues.proconfig THEN
   RAISE EXCEPTION 'B65: postimagen incompatible para %',esperado.firma USING ERRCODE='55000';
  END IF;
 END LOOP;
END $correctiva$;
COMMIT;
